import {CITIES} from './places.js';
import {esc} from './weather-tools.js';
export function createChallenges(ctx){
 let data=null,busy=false,error='',identityKey='',chosen='roma',updated=0;
 const name=id=>CITIES.find(c=>c.id===id)?.name||id;
 function page(){const id=ctx.get().me?.id||'guest';if(identityKey!==id){identityKey=id;data=null;updated=0}const selected=CITIES.find(c=>c.name===ctx.get().place.name);if(!data?.mine&&selected)chosen=selected.id;return `<section class="challenge-workspace"><div class="atlas-title"><div><h1>Un cielo. La tua città.</h1><p>Una sfida settimanale per raccontare il mondo insieme.</p></div><a href="#community">Community →</a></div><section class="challenge-hero"><div><span class="challenge-season">SFIDA DELLA SETTIMANA · ATLANTE DEI CIELI</span><h2>Sette giorni.<br>Sette punti di vista.</h2><p>Una foto o un breve video del cielo al giorno. Nuvole, luce e piccoli cambiamenti, ripresi da un posto sicuro.</p><span>${data?'Fino a '+new Date(data.ends).toLocaleDateString('it-IT',{day:'numeric',month:'long'})+' · 00:00 UTC':'Settimana da lunedì a domenica, orario UTC'}</span></div><div class="challenge-progress"><strong>${data?.entries.length||0}<small>/ 7</small></strong><span>I tuoi contributi questa settimana</span><div class="challenge-dots" aria-hidden="true">${Array.from({length:7},(_,i)=>`<i class="${i<(data?.entries.length||0)?'done':''}"></i>`).join('')}</div></div></section><div class="challenge-layout"><section class="challenge-card"><h2>${data?.mine?'Giochi con '+esc(name(data.mine)):'Scegli la tua città'}</h2><label class="field">Squadra<select id="challenge-city" aria-label="Squadra">${CITIES.map(c=>`<option value="${c.id}" ${c.id===(data?.mine||chosen)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><button class="button wide" data-challenge-join>${data?.mine?'Aggiorna squadra':'Partecipa alla sfida'}</button><p>Dopo il primo contributo, la squadra resta la stessa fino alla prossima settimana.</p><div class="challenge-how"><b>Come aggiungere un punto</b><ol><li>Pubblica una tua foto o un video nella città scelta.</li><li>Scegli “Osservazione” o “Cielo sereno”.</li><li>Nel tuo post premi “Aggiungi alla sfida”.</li></ol></div><button data-challenge-compose class="button wide">＋ Racconta il cielo</button><a href="#clan">I gruppi della community →</a></section><section class="challenge-card"><div class="near-heading"><h2>Classifica delle città</h2><button data-challenge-refresh>Aggiorna</button></div>${error?`<p role="alert">${esc(error)}</p>`:!data?'<p role="status">Caricamento della classifica…</p>':data.board.length?`<ol class="city-leaderboard">${data.board.map((c,i)=>`<li><span>${c.points?data.board.findIndex(v=>v.points===c.points)+1:'—'}</span><div><b>${esc(c.name)}</b><small>${c.contributors} partecipanti con contributi · ${c.members} iscritti</small></div><strong>${c.points}<small>punti</small></strong></li>`).join('')}</ol>`:'<div class="near-empty"><h3>La prima squadra può essere la tua.</h3><p>La classifica mostrerà iscrizioni e contributi reali.</p></div>'}</section></div><details class="challenge-rules"><summary>Regole chiare per tutti</summary><p>Un punto per persona e giorno UTC, massimo sette a settimana. Conta il giorno di pubblicazione del post. Sono ammessi foto e video propri pubblicati in questa settimana come “Osservazione” o “Cielo sereno”. La città deve coincidere con la squadra.</p><p>Le segnalazioni di pericolo non danno punti. Non uscire o spostarti durante un evento per partecipare. Una foto da una finestra va bene. I contributi sono dichiarati dagli autori, non certificati dall’IA.</p><p>Eliminando il post il punto scompare dalla classifica, ma la quota di quel giorno resta utilizzata per evitare duplicati. Non ci sono premi economici o punti per like; le città a pari punteggio condividono la posizione.</p></details></section>`}
 async function load(){if(busy)return;busy=true;error='';const user=ctx.get().me?.id;try{const d=await ctx.api('pulse/challenges');if(ctx.get().me?.id!==user)return;data=d;updated=Date.now()}catch(e){error=e.message;updated=Date.now()}finally{busy=false;if(ctx.get().route==='sfide')ctx.render()}}
 function bind(){if(ctx.get().route!=='sfide')return;if(!busy&&Date.now()-updated>60000)load();document.querySelector('[data-challenge-refresh]')?.addEventListener('click',load);document.querySelector('[data-challenge-join]')?.addEventListener('click',async e=>{if(!ctx.get().me)return ctx.login();e.target.disabled=true;try{chosen=document.querySelector('#challenge-city').value;await ctx.api('pulse/join',{city:chosen});await load();ctx.toast('Sei nella squadra di '+name(chosen)+'.')}catch(e){ctx.toast(e.message)}finally{e.target.disabled=false}});document.querySelector('[data-challenge-compose]')?.addEventListener('click',()=>{if(!data?.mine)return ctx.toast('Scegli prima una squadra e premi Partecipa.');ctx.compose(name(data.mine))})}
 return {page,bind,invalidate(){updated=0;data=null}};
}
